(2, 'ORD-91402', 2, 3, 'В обработке', 13980, '2026-04-02'),
(3, 'ORD-91377', 3, 4, 'Доставлен', 11500, '2026-04-02'),
(4, 'ORD-91320', 1, 1, 'В обработке', 18990, '2026-04-01'),
(5, 'ORD-91290', 2, 3, 'Доставлен', 6990, '2026-03-31');

